-- D. ET0 / PET annual sums (meteorological_drought_master), AET (runoff table): 2000, 2025, mean, days per year; Sen's slope ET0; districts
WITH {W}, y AS (SELECT w.code, w.area, year yr, sum(et0_mm_day) et0, sum(pet_mm_day) pet, count(et0_mm_day) days FROM meteorological_drought_master t JOIN w ON w.name=t.district_name WHERE year BETWEEN 2000 AND 2025 GROUP BY 1,2,3),
a AS (SELECT yr, sum(area*et0)/sum(area) et0, sum(area*pet)/sum(area) pet, min(days) mind, max(days) maxd FROM y GROUP BY 1),
q AS (SELECT w.code, w.area, extract(year from "Date")::int yr, sum("Actual_ET_from_Catchment_mm") aet FROM runoff_variables_master t JOIN w ON w.name=t."District_Name" WHERE extract(year from "Date") BETWEEN 2000 AND 2025 GROUP BY 1,2,3),
qa AS (SELECT yr, sum(area*aet)/sum(area) aet FROM q GROUP BY 1)
SELECT (SELECT round(et0::numeric,1)||'/'||round(pet::numeric,0)||'/'||mind||'-'||maxd FROM a WHERE yr=2000) et0_pet_days_2000, (SELECT round(et0::numeric,1)||'/'||round(pet::numeric,0)||'/'||mind||'-'||maxd FROM a WHERE yr=2025) et0_pet_days_2025,
 round(avg(et0)::numeric,1) et0_mean, round(((SELECT et0 FROM a WHERE yr=2025) - avg(et0))::numeric,0) et0_delta, round(stddev_samp(et0)::numeric,1) et0_sd,
 (SELECT round((percentile_cont(0.5) WITHIN GROUP (ORDER BY (b.et0-a.et0)/(b.yr-a.yr)) * 10)::numeric,1) FROM a a JOIN a b ON b.yr > a.yr) et0_sen10,
 (SELECT round(aet::numeric,0) FROM qa WHERE yr=2000) aet2000, (SELECT round(aet::numeric,0) FROM qa WHERE yr=2025) aet2025,
 (SELECT string_agg(code||':'||e25||'('||round(d::numeric,0)||')/'||mn, ' ' ORDER BY code) FROM (SELECT code, round(max(et0) FILTER (WHERE yr=2025)::numeric,0) e25, max(et0) FILTER (WHERE yr=2025) - avg(et0) d, round(avg(et0)::numeric,0) mn FROM y WHERE code IN ('CPT','DC34','DC44') GROUP BY 1) x) districts_et0_2025_delta_mean FROM a;;
-- D2. 31 December present? days per year in meteorological / 4_1 / runoff / 6.1 for 2025 (one district)
SELECT (SELECT count(*) FROM meteorological_drought_master WHERE district_name='Vhembe' AND year=2025) met_2025, (SELECT count(*) FROM meteorological_drought_master WHERE district_name='Vhembe' AND date='2025-12-31') met_dec31,
 (SELECT count(*) FROM "4_1_temperature_change_master" WHERE "District_Name"='Vhembe' AND "Date" LIKE '2025-%') t41_2025, (SELECT count(*) FROM runoff_variables_master WHERE "District_Name"='Vhembe' AND extract(year from "Date")=2025) runoff_2025, (SELECT count(*) FROM "6.1_core_rainfall_variables_master" WHERE "District_Name"='Vhembe' AND "Year"=2025) r61_2025;;
-- E. annual runoff depth (mm) national + districts: 2000, 2025, mean 2000-2025, anomaly, Sen's slope
WITH {W}, y AS (SELECT w.code, w.area, extract(year from "Date")::int yr, sum("Daily_Surface_Runoff_Volume_m3_day")/6.5e9*1000 q FROM runoff_variables_master t JOIN w ON w.name=t."District_Name" WHERE extract(year from "Date") BETWEEN 2000 AND 2025 GROUP BY 1,2,3),
a AS (SELECT yr, sum(area*q)/sum(area) v FROM y GROUP BY 1)
SELECT (SELECT round(v::numeric,1) FROM a WHERE yr=2000) q2000, (SELECT round(v::numeric,1) FROM a WHERE yr=2025) q2025, round(avg(v)::numeric,1) mean, round((((SELECT v FROM a WHERE yr=2025)-avg(v))/avg(v)*100)::numeric,1) anomaly_pct, round((((SELECT v FROM a WHERE yr=2000)-avg(v))/avg(v)*100)::numeric,1) anomaly_2000, round(stddev_samp(v)::numeric,1) sd,
 (SELECT round((percentile_cont(0.5) WITHIN GROUP (ORDER BY (b.v-a.v)/(b.yr-a.yr)) * 10)::numeric,1) FROM a a JOIN a b ON b.yr > a.yr) sen10,
 (SELECT string_agg(code||':'||round(((q25-mn)/mn*100)::numeric,1)||'('||round(mn::numeric,0)||')', ' ' ORDER BY code) FROM (SELECT code, max(q) FILTER (WHERE yr=2025) q25, avg(q) mn FROM y WHERE code IN ('CPT','DC34','DC44') GROUP BY 1) x) districts FROM a;;
-- M. provinces table hot days 2025 with distinct code weights
WITH {W}, {WC}, h AS (SELECT w.code, max("Heatwave_Frequency_Days") hh FROM "4_1_temperature_change_master" t JOIN w ON w.name=t."District_Name" WHERE left("Date",4)='2025' GROUP BY 1)
SELECT wc.prov, round((sum(wc.area*hh)/sum(wc.area))::numeric,1) hot FROM h JOIN wc ON wc.code=h.code GROUP BY 1 ORDER BY 1;;
-- T. SPI rounding ties: district-months whose SPI-3 lies within 0.0005 of a class boundary + 0.005 (x.xx5 values), 2020 and overall; how many decimals do SPI values have?
SELECT "District_Name", "Year", "Month", "SPI_3_Short_Term_Agricultural_Drought" v, "SPI_3_Short_Term_Agricultural_Drought"::text txt FROM "6.2_rainfall_derived_drought_indices_master" WHERE "Year"=2020 AND "SPI_3_Short_Term_Agricultural_Drought" BETWEEN -1.3051 AND -1.2949 ORDER BY 2,3;;
SELECT count(*) n, count(*) FILTER (WHERE length(split_part(abs(v)::text,'.',2)) <= 2) dp2, count(*) FILTER (WHERE length(split_part(abs(v)::text,'.',2)) = 3) dp3, count(*) FILTER (WHERE length(split_part(abs(v)::text,'.',2)) > 3) dp4plus,
 count(*) FILTER (WHERE v IN (-0.495,-0.795,-1.295,-1.595,-1.995)) ties_above_threshold FROM (SELECT "SPI_3_Short_Term_Agricultural_Drought" v FROM "6.2_rainfall_derived_drought_indices_master" UNION ALL SELECT "SPI_6_Medium_Term_Hydrological_Impacts" FROM "6.2_rainfall_derived_drought_indices_master" UNION ALL SELECT "SPI_12_Long_Term_Groundwater_Impacts" FROM "6.2_rainfall_derived_drought_indices_master" UNION ALL SELECT "SPI_1_Meteorological_Drought_Onset" FROM "6.2_rainfall_derived_drought_indices_master" UNION ALL SELECT "SPI_24_Very_Long_Term_Drought" FROM "6.2_rainfall_derived_drought_indices_master") x WHERE v IS NOT NULL;;
SELECT "Year", count(*) FROM "6.2_rainfall_derived_drought_indices_master" WHERE "SPI_6_Medium_Term_Hydrological_Impacts" IN (-0.495,-0.795,-1.295,-1.595,-1.995) OR "SPI_3_Short_Term_Agricultural_Drought" IN (-0.495,-0.795,-1.295,-1.595,-1.995) GROUP BY 1 ORDER BY 1;;
